import { Component, OnInit } from "@angular/core";
import { FormBuilder, FormGroup, Validators } from "@angular/forms";
import { ProductService } from "../../services/product.service";
import { OrderService } from "../../services/order.service";
import { Product } from "../../models/product";
import { Order } from "../../models/order";

@Component({
  selector: "app-admin",
  templateUrl: "./admin.component.html",
  styleUrls: ["./admin.component.css"],
})
export class AdminComponent implements OnInit {
  activeTab: "products" | "orders" = "products";
  products: Product[] = [];
  orders: Order[] = [];
  productForm!: FormGroup;
  editingProduct: Product | null = null;
  showForm = false;
  successMsg = "";

  constructor(
    private productService: ProductService,
    private orderService: OrderService,
    private fb: FormBuilder,
  ) {}

  ngOnInit(): void {
    this.loadProducts();
    this.loadOrders();
    this.initForm();
  }

  initForm(product?: Product): void {
    this.productForm = this.fb.group({
      name: [product?.name || "", Validators.required],
      description: [product?.description || "", Validators.required],
      price: [product?.price || "", [Validators.required, Validators.min(1)]],
      imageUrl: [product?.imageUrl || "", Validators.required],
      category: [product?.category || "", Validators.required],
      stock: [product?.stock || "", [Validators.required, Validators.min(0)]],
    });
  }

  loadProducts(): void {
    this.productService.getProducts().subscribe((p) => (this.products = p));
  }

  loadOrders(): void {
    this.orderService.getOrders().subscribe((o) => (this.orders = o));
  }

  openAddForm(): void {
    this.editingProduct = null;
    this.initForm();
    this.showForm = true;
  }

  openEditForm(product: Product): void {
    this.editingProduct = product;
    this.initForm(product);
    this.showForm = true;
  }

  cancelForm(): void {
    this.showForm = false;
    this.editingProduct = null;
  }

  submitForm(): void {
    if (this.productForm.invalid) {
      this.productForm.markAllAsTouched();
      return;
    }
    const data = this.productForm.value;
    if (this.editingProduct) {
      this.productService
        .updateProduct(this.editingProduct.id, {
          ...data,
          id: this.editingProduct.id,
        })
        .subscribe(() => {
          this.showMsg("Product updated!");
          this.cancelForm();
        });
    } else {
      this.productService.addProduct(data).subscribe(() => {
        this.showMsg("Product added!");
        this.cancelForm();
      });
    }
  }

  deleteProduct(id: number): void {
    if (confirm("Delete this product?")) {
      this.productService
        .deleteProduct(id)
        .subscribe(() => this.showMsg("Product deleted!"));
    }
  }

  showMsg(msg: string): void {
    this.successMsg = msg;
    setTimeout(() => (this.successMsg = ""), 3000);
  }
}
<div class="admin-page">
  <div class="admin-header">
    <h1>Admin Dashboard</h1>
    <div class="success-toast" *ngIf="successMsg">✅ {{ successMsg }}</div>
  </div>

  <div class="admin-tabs">
    <button
      [class.active]="activeTab === 'products'"
      (click)="activeTab = 'products'"
    >
      Products
    </button>
    <button
      [class.active]="activeTab === 'orders'"
      (click)="activeTab = 'orders'"
    >
      Orders
    </button>
  </div>

  <!-- Products Tab -->
  <div *ngIf="activeTab === 'products'">
    <div class="tab-toolbar">
      <h2>Manage Products ({{ products.length }})</h2>
      <button class="add-btn" (click)="openAddForm()">+ Add Product</button>
    </div>

    <!-- Product Form Modal -->
    <div class="modal-overlay" *ngIf="showForm" (click)="cancelForm()">
      <div class="modal" (click)="$event.stopPropagation()">
        <h3>{{ editingProduct ? "Edit Product" : "Add New Product" }}</h3>
        <form [formGroup]="productForm" (ngSubmit)="submitForm()">
          <div class="form-group">
            <label>Product Name</label>
            <input formControlName="name" placeholder="Product name" />
            <span
              class="err"
              *ngIf="
                productForm.get('name')?.invalid &&
                productForm.get('name')?.touched
              "
              >Required</span
            >
          </div>
          <div class="form-group">
            <label>Description</label>
            <textarea
              formControlName="description"
              placeholder="Product description"
              rows="3"
            ></textarea>
          </div>
          <div class="form-row">
            <div class="form-group">
              <label>Price (₹)</label>
              <input type="number" formControlName="price" placeholder="0" />
            </div>
            <div class="form-group">
              <label>Stock</label>
              <input type="number" formControlName="stock" placeholder="0" />
            </div>
          </div>
          <div class="form-group">
            <label>Category</label>
            <select formControlName="category">
              <option value="">Select...</option>
              <option>Electronics</option>
              <option>Sports</option>
              <option>Home</option>
              <option>Accessories</option>
            </select>
          </div>
          <div class="form-group">
            <label>Image URL</label>
            <input formControlName="imageUrl" placeholder="https://..." />
          </div>
          <div class="modal-actions">
            <button type="submit" class="save-btn">
              {{ editingProduct ? "Update" : "Add" }} Product
            </button>
            <button type="button" class="cancel-btn" (click)="cancelForm()">
              Cancel
            </button>
          </div>
        </form>
      </div>
    </div>

    <!-- Products Table -->
    <div class="table-wrap">
      <table class="data-table">
        <thead>
          <tr>
            <th>Image</th>
            <th>Name</th>
            <th>Category</th>
            <th>Price</th>
            <th>Stock</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          <tr *ngFor="let p of products">
            <td><img [src]="p.imageUrl" [alt]="p.name" class="table-img" /></td>
            <td>
              <strong>{{ p.name }}</strong>
            </td>
            <td>
              <span class="badge">{{ p.category }}</span>
            </td>
            <td>₹{{ p.price | number }}</td>
            <td [class.low-stock]="p.stock < 5">{{ p.stock }}</td>
            <td class="actions-cell">
              <button class="edit-btn" (click)="openEditForm(p)">
                ✏️ Edit
              </button>
              <button class="del-btn" (click)="deleteProduct(p.id)">
                🗑️ Delete
              </button>
            </td>
          </tr>
        </tbody>
      </table>
    </div>
  </div>

  <!-- Orders Table -->
  <div *ngIf="activeTab === 'orders'">
    <div class="tab-toolbar">
      <h2>All Orders ({{ orders.length }})</h2>
    </div>
    <div class="empty-orders" *ngIf="orders.length === 0">
      <p>No orders yet. Orders placed by customers will appear here.</p>
    </div>
    <div class="table-wrap" *ngIf="orders.length > 0">
      <table class="data-table">
        <thead>
          <tr>
            <th>Order ID</th>
            <th>Customer</th>
            <th>Email</th>
            <th>Total</th>
            <th>Status</th>
            <th>Date</th>
          </tr>
        </thead>
        <tbody>
          <tr *ngFor="let o of orders">
            <td>
              <strong>#{{ o.id }}</strong>
            </td>
            <td>{{ o.customerName }}</td>
            <td>{{ o.customerEmail }}</td>
            <td>₹{{ o.total | number }}</td>
            <td>
              <span class="status-badge">{{ o.status }}</span>
            </td>
            <td>{{ o.createdAt | date: "short" }}</td>
          </tr>
        </tbody>
      </table>
    </div>
  </div>
</div>
